import type { Agent } from "./agent.ts";

/** YAML scalar that survives any character: a JSON string is a valid YAML double-quoted string. */
export const yamlString = (value: string): string => JSON.stringify(value);

/** How every generated file starts its banner: `sync` only ever removes files that carry it. */
export const GENERATED_MARKER = "<!-- Generated by aidt sync from ";

/** Banner placed right after the frontmatter, where tools still read the file correctly. */
export const generatedBanner = (source: string): string =>
  `${GENERATED_MARKER}${source}. Edit that file and run \`aidt sync\`. -->`;

/** How agents run the CLI when it is not installed globally (`npx` resolves the scoped package). */
const NPX_AIDT = "npx @akiles94/ai-dev-toolkit";

/**
 * The command prefixes an agent may run. Every `aidt …` command is also allowed through `npx`,
 * so agents work in projects that never ran `npm i -g`.
 */
export function allowedCommands(agent: Agent): string[] {
  const viaNpx = agent.commands
    .filter((c) => c.startsWith("aidt "))
    .map((c) => `${NPX_AIDT} ${c.slice("aidt ".length)}`);
  return [...agent.commands, ...viaNpx];
}

/** Tells the agent how to fall back to `npx` when `aidt` is missing. Empty if it runs no `aidt`. */
function npxNote(agent: Agent): string[] {
  if (!agent.commands.some((c) => c.startsWith("aidt "))) return [];
  return [
    "",
    `If \`aidt\` is not installed, run the same command as \`${NPX_AIDT} …\` (for example`,
    `\`${NPX_AIDT} diff --json\`). Never count lines or search for guide comments by hand instead.`,
  ];
}

/**
 * The agent's file and command limits written as instructions, for tools that cannot enforce them
 * as permissions. Empty when the agent has no scoped capability.
 */
export function limitsSection(agent: Agent): string {
  const lines: string[] = [];
  if (agent.writes.length > 0) {
    lines.push("Create or change only these files:", ...agent.writes.map((g) => `- \`${g}\``));
  }
  if (agent.commands.length > 0) {
    const commands = allowedCommands(agent).map((c) => `- \`${c}\``);
    lines.push("Run only commands starting with:", ...commands);
  }
  if (!agent.capabilities.includes("edit")) lines.push("Never change source code.");
  lines.push(...npxNote(agent));
  return lines.length === 0 ? "" : ["## Limits", "", ...lines].join("\n");
}

/** Joins the parts of a generated Markdown file, skipping empty ones. */
export const markdown = (...parts: string[]): string =>
  `${parts.filter((part) => part !== "").join("\n\n")}\n`;
